#include <cuda_runtime.h>
#include <cub/block/block_reduce.cuh>
#include <stddef.h>

namespace {
constexpr int kBlockThreads = 256;
constexpr int kItemsPerThread = 8;
constexpr int kTileItems = kBlockThreads * kItemsPerThread;

__global__ void reduce_input_blocks(const int *input, int *partials, int n)
{
    using BlockReduce = cub::BlockReduce<int, kBlockThreads>;
    __shared__ typename BlockReduce::TempStorage temp_storage;

    const size_t block_base = static_cast<size_t>(blockIdx.x) * kTileItems;
    int thread_sum = 0;
#pragma unroll
    for (int item = 0; item < kItemsPerThread; ++item) {
        const size_t index = block_base + threadIdx.x +
                             static_cast<size_t>(item) * kBlockThreads;
        if (index < static_cast<size_t>(n)) {
            thread_sum += input[index];
        }
    }

    const int block_sum = BlockReduce(temp_storage).Sum(thread_sum);
    if (threadIdx.x == 0) {
        partials[blockIdx.x] = block_sum;
    }
}

__global__ void reduce_partials(const int *partials, int partial_count, int *out)
{
    using BlockReduce = cub::BlockReduce<int, kBlockThreads>;
    __shared__ typename BlockReduce::TempStorage temp_storage;

    int thread_sum = 0;
    for (int index = static_cast<int>(threadIdx.x); index < partial_count;
         index += kBlockThreads) {
        thread_sum += partials[index];
    }

    const int total = BlockReduce(temp_storage).Sum(thread_sum);
    if (threadIdx.x == 0) {
        out[0] = total;
    }
}
} // namespace

extern "C" void run(const void *x, const void *, const void *, void *out,
                    void *scratch, int n, int, int, int)
{
    if (n <= 0) {
        cudaMemsetAsync(out, 0, sizeof(int));
        return;
    }

    const int *input = static_cast<const int *>(x);
    int *output = static_cast<int *>(out);

    if (n <= kTileItems) {
        reduce_input_blocks<<<1, kBlockThreads>>>(input, output, n);
        return;
    }

    const int partial_count = n / kTileItems + (n % kTileItems != 0);
    int *partials = static_cast<int *>(scratch);
    reduce_input_blocks<<<partial_count, kBlockThreads>>>(input, partials, n);
    reduce_partials<<<1, kBlockThreads>>>(partials, partial_count, output);
}

#include <cuda_runtime.h>

namespace {
enum : unsigned int {
    kBlockThreads = 256u,
    kWarpSize = 32u,
    kWarpCount = kBlockThreads / kWarpSize,
    kValuesPerThread = 16u,
    kTileElements = kBlockThreads * kValuesPerThread
};

__device__ __forceinline__ unsigned int warp_sum(unsigned int value)
{
    for (int offset = 16; offset > 0; offset >>= 1) {
        value += __shfl_down_sync(0xffffffffu, value, offset);
    }
    return value;
}

__device__ __forceinline__ unsigned int block_sum(
    unsigned int value, unsigned int* warp_sums)
{
    const unsigned int lane = threadIdx.x & (kWarpSize - 1u);
    const unsigned int warp = threadIdx.x / kWarpSize;

    value = warp_sum(value);
    if (lane == 0u) {
        warp_sums[warp] = value;
    }
    __syncthreads();

    if (warp == 0u) {
        value = lane < kWarpCount ? warp_sums[lane] : 0u;
        value = warp_sum(value);
    }
    return value;
}

__global__ void reduce_single(const unsigned int* input,
                              unsigned int* output,
                              unsigned int count)
{
    __shared__ unsigned int warp_sums[kWarpCount];
    unsigned int sum = 0u;

    for (unsigned int i = threadIdx.x; i < count; i += kBlockThreads) {
        sum += input[i];
    }

    const unsigned int total = block_sum(sum, warp_sums);
    if (threadIdx.x == 0u) {
        output[0] = total;
    }
}

__global__ void reduce_tiles(const unsigned int* input,
                             unsigned int* partials,
                             unsigned int count)
{
    __shared__ unsigned int warp_sums[kWarpCount];
    const unsigned int tile_base = blockIdx.x * kTileElements;
    unsigned int sum = 0u;

    // Each round gives every warp a contiguous, coalesced segment.
    for (unsigned int j = 0; j < kValuesPerThread; ++j) {
        const unsigned int index = tile_base + j * kBlockThreads + threadIdx.x;
        if (index < count) {
            sum += input[index];
        }
    }

    const unsigned int total = block_sum(sum, warp_sums);
    if (threadIdx.x == 0u) {
        partials[blockIdx.x] = total;
    }
}

__global__ void reduce_partials(const unsigned int* partials,
                                unsigned int* output,
                                unsigned int count)
{
    __shared__ unsigned int warp_sums[kWarpCount];
    unsigned int sum = 0u;

    for (unsigned int i = threadIdx.x; i < count; i += kBlockThreads) {
        sum += partials[i];
    }

    const unsigned int total = block_sum(sum, warp_sums);
    if (threadIdx.x == 0u) {
        output[0] = total;
    }
}
} // namespace

extern "C" void run(const void* x, const void*, const void*, void* out,
                    void* scratch, int n, int, int, int)
{
    const unsigned int count = n > 0 ? static_cast<unsigned int>(n) : 0u;
    const unsigned int* input = reinterpret_cast<const unsigned int*>(x);
    unsigned int* output = reinterpret_cast<unsigned int*>(out);

    if (count <= kTileElements) {
        reduce_single<<<1, kBlockThreads>>>(input, output, count);
        return;
    }

    const unsigned int partial_count =
        count / kTileElements + (count % kTileElements != 0u);
    unsigned int* partials = reinterpret_cast<unsigned int*>(scratch);
    reduce_tiles<<<partial_count, kBlockThreads>>>(input, partials, count);
    reduce_partials<<<1, kBlockThreads>>>(partials, output, partial_count);
}

